{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Rac-thalidomide, a lipophilic, poorly water-soluble neutral drug, showed probably high absolute oral bioavailability of 80–100% in fasting healthy volunteers, supporting that such compounds can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "(S)-Thalidomide had an absolute oral bioavailability of about 80% in healthy volunteers, providing direct human evidence that a related lipophilic heterocycle can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Zilascorb(2H) tablets had an absolute plasma-derived bioavailability of 32 ± 12% in patients, a direct human absolute-F value above the 20% threshold and consistent with a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Bepotastine, a chlorophenyl-containing drug, showed >80% oral bioavailability in humans, supporting high oral absorption for structurally related lipophilic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiludronic acid had an absolute oral bioavailability of only 6% (2–11%) in healthy volunteers, a contradictory low-F example, but its highly polar bisphosphonate structure has low transferability to the lipophilic naphthoquinone query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Danavorexton had poor oral bioavailability requiring IV infusion, a contradictory low-F example, but its sulfonamide-containing structure and metabolic liabilities are not representative of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic, poorly water-soluble naphthoquinone; under fed conditions, food-enhanced solubilization is expected to raise its oral bioavailability above the 20% threshold. Supportive human absolute-F evidence from lipophilic/neutral and chlorophenyl-containing drugs outweighs low-F examples that are structurally dissimilar and poorly transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself under fed conditions is present in the evidence set.",
    "Most evidence records do not explicitly match the fed-state condition, so the food effect is inferred from the query's solubility-limited absorption profile.",
    "Sertraline evidence is conflicting and its first-pass metabolism differs from the query, limiting its usefulness."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

